fn check_all_lowercase(v: &Vec<char>) -> bool {
    // Return false on empty input
    if v.is_empty() {
        return false;
    }
    // Check that every character is in 'a'..='z'
    for &c in v.iter() {
        if !(c >= 'a' && c <= 'z') {
            return false;
        }
    }
    true
}

fn solve(input: Vec<char>) -> Vec<char> {
    if check_all_lowercase(&input) {
        vec!['a']
    } else {
        vec!['A']
    }
}

